package main

import "fmt"

// tryPublish never blocks: when the buffer is full the event is dropped
// and the caller learns about it, instead of stalling the request path.
func tryPublish(events chan<- string, e string) bool {
	select {
	case events <- e:
		return true
	default:
		return false
	}
}

func main() {
	events := make(chan string, 2) // room for two events, no consumer yet
	for _, e := range []string{"login", "view", "click"} {
		fmt.Println(e, "queued:", tryPublish(events, e))
	}

	// Non-blocking receive: drain what is buffered, stop when it is empty.
	for drained := false; !drained; {
		select {
		case e := <-events:
			fmt.Println("handled", e)
		default:
			drained = true
		}
	}

	// A closed channel is always ready to receive. With two ready cases,
	// select picks one at random: the first case gets no priority.
	a, b := make(chan struct{}), make(chan struct{})
	close(a)
	close(b)
	var fromA, fromB int
	for range 1000 {
		select {
		case <-a:
			fromA++
		case <-b:
			fromB++
		}
	}
	fmt.Println("both cases chosen:", fromA > 0 && fromB > 0)
}

files.examples/03_multiplex.go:
package main

import (
	"fmt"
	"time"
)

// produce sends n events and closes its channel: the sender owns the close.
func produce(kind string, n int) <-chan string {
	ch := make(chan string)
	go func() {
		defer close(ch)
		for i := 1; i <= n; i++ {
			ch <- fmt.Sprintf("%s-%d", kind, i)
		}
	}()
	return ch
}

func main() {
	orders, refunds := produce("order", 3), produce("refund", 2)
	got := map[string][]string{}

	// One timer for the whole loop: an overall deadline, not per message.
	deadline := time.After(time.Second)

	// A nil channel is never ready, so setting a finished input to nil
	// switches its case off. The loop ends when both inputs are done.
	for orders != nil || refunds != nil {
		select {
		case o, ok := <-orders:
			if !ok {
				orders = nil
				continue
			}
			got["order"] = append(got["order"], o)
		case r, ok := <-refunds:
			if !ok {
				refunds = nil
				continue
			}
			got["refund"] = append(got["refund"], r)
		case <-deadline:
			fmt.Println("gave up waiting")
			return
		}
	}
	// How the two streams interleave varies per run; the order within
	// each channel never does.
	fmt.Println(got["order"])
	fmt.Println(got["refund"])
}
